                Comm32.LogDebugInfo("Closing Write Thread");
                Rtl.SetEvent(hCloseEvent);
                PurgeComm(hCommFile, PURGE_TXABORT + PURGE_TXCLEAR);
                if (WaitForSingleObject(WriteThread.Handle, 10000) == WAIT_TIMEOUT)
                {
                    Comm32.LogDebugInfo("Write thread not exiting.  Terminating it.");
                    WriteThread.Terminate();
                }
                /* WriteThread.Free - not needed (garbage collected) */;
                WriteThread = null;
            }
        }

        // Delphi: procedure TComm32.ReceiveData(Buffer: PChar; BufferLength: Word)
        protected internal void ReceiveData(string Buffer, ushort BufferLength)
        {
            if (FOnReceiveData != null)
            {
                FOnReceiveData(Buffer, BufferLength);
            }
        }

        // Delphi: procedure TComm32.RequestHangup
        protected internal void RequestHangup()
        {
            if (FOnRequestHangup != null)
            {
                FOnRequestHangup(this);
            }
        }

        // Delphi: destructor TComm32.Destroy
        public virtual void Destroy()
        {
            if (!Rtl.ComponentState.Contains(Rtl.csDesigning))
            {
                DeallocateHWnd(FHWnd);
            }
            /* inherited Destroy - VCL ancestor call removed */;
        }

        // Delphi: function TComm32.StartComm: Boolean
        public bool StartComm()
        {
            bool Result = false;
            dynamic /* TCommTimeouts */ commtimeouts = null;
            dynamic /* Tdcb */ dcb = null;
            dynamic /* TCommProp */ commprop = null;
            uint fdwEvtMask = (uint)0;
            uint hNewCommFile = (uint)0;
            if (hCommFile != 0)
            {
                throw new ECommsError("Already have a comm file open");
            }
            if (CommsLogFileName != "")
            {
                Rtl.AssignFile(Comm32.CommsLogFile, FCommsLogFileName);
                Rtl.Rewrite(Comm32.CommsLogFile);
            }
            hNewCommFile = CreateFile(Rtl.PChar(FCommPort), JwaWinNT.GENERIC_READ + JwaWinNT.GENERIC_WRITE, 0, null, OPEN_EXISTING, FILE_FLAG_OVERLAPPED, 0);
            if (hNewCommFile == INVALID_HANDLE_VALUE)
            {
                throw new ECommsError("Error opening com port");
            }
            if (GetFileType(hNewCommFile) != FILE_TYPE_CHAR)
            {
                throw new ECommsError("File handle is not a comm handle. ");
            }
            hCommFile = hNewCommFile;
            GetCommState(hNewCommFile, dcb);
            GetCommProperties(hNewCommFile, commprop);
            GetCommMask(hCommFile, fdwEvtMask);
            GetCommTimeouts(hCommFile, commtimeouts);
            commtimeouts.ReadIntervalTimeout = 250;
            commtimeouts.ReadTotalTimeoutMultiplier = 0;
            commtimeouts.ReadTotalTimeoutConstant = 0;
            commtimeouts.WriteTotalTimeoutMultiplier = 0;
            commtimeouts.WriteTotalTimeoutConstant = 0;
            SetCommTimeouts(hCommFile, commtimeouts);
            dcb.BaudRate = FBaudRate;
            dcb.Parity = (int)FParity;
            dcb.StopBits = (int)FStopBits;
            SetCommState(hNewCommFile, dcb);
            hCloseEvent = CreateEvent(null, true, false, null);
            if (hCloseEvent == 0)
            {
                Comm32.LogDebugLastError((uint)Rtl.GetLastError(), "Unable to CreateEvent: ");
                hCommFile = 0;
                Result = false;
                return Result;
            }
            try
            {
                ReadThread = new TReadThread(true);
            }
            catch (Exception)
            {
                Comm32.LogDebugLastError((uint)Rtl.GetLastError(), "Unable to create Read thread");
                throw new ECommsError("Unable to create Read thread");
            }
            ReadThread.hCommFile = hCommFile;
            ReadThread.hCloseEvent = hCloseEvent;
            ReadThread.hComm32Window = FHWnd;
            ReadThread.Start();
            ReadThread.Priority = tpHighest;
            try
            {
                WriteThread = new TWriteThread(true);
            }
            catch (Exception)
            {
                Comm32.LogDebugLastError((uint)Rtl.GetLastError(), "Unable to create Write thread");
                throw new ECommsError("Unable to create Write thread");
            }
            WriteThread.hCommFile = hCommFile;
            WriteThread.hCloseEvent = hCloseEvent;
            WriteThread.hComm32Window = FHWnd;
            WriteThread.Start();
            WriteThread.Priority = tpHigher;
            while (!(WriteCreated && ReadCreated || ThreadError))
            {
                Rtl.Application.ProcessMessages();
            }
            Result = true;
            return Result;
        }

        // Delphi: procedure TComm32.StopComm
        public void StopComm()
        {
            if (hCommFile == 0)
            {
                return;
            }
            Comm32.LogDebugInfo("Stopping the Comm");
            CloseReadThread();
            CloseWriteThread();
            CloseHandle(hCloseEvent);
            CloseHandle(hCommFile);
            hCommFile = 0;
            if (FCommsLogFileName != "")
            {
                Rtl.CloseFile(Comm32.CommsLogFile);
            }
        }

        // Delphi: function TComm32.WriteCommData(pDataToWrite: PChar; dwSizeofDataToWrite: Word): Boolean
        public bool WriteCommData(string pDataToWrite, ushort dwSizeofDataToWrite)
        {
            bool Result = false;
            IntPtr Buffer = IntPtr.Zero;
            if (WriteThread != null)
            {
                Buffer = LocalAlloc(LPTR, dwSizeofDataToWrite + 1) /* Pointer(...) */;
                /* TODO: Move(pDataToWrite, Buffer /* ^ * /, dwSizeofDataToWrite) */;
                if (PostThreadMessage(WriteThread.ThreadID, Comm32.PWM_COMMWRITE, (uint)dwSizeofDataToWrite, System.Convert.ToInt32(Buffer)))
                {
                    Result = true;
                    return Result;
                }
                else
                {
                    Comm32.LogDebugInfo("Failed to Post to Write thread. ");
                }
            }
            else
            {
                Comm32.LogDebugInfo("Write thread not created");
            }
            Result = false;
            return Result;
        }

    }

    /// <summary>
    /// Global constants, variables and routines of Delphi unit Comm32.
    /// </summary>
    public static partial class Comm32
    {
        public static readonly int PWM_GOTCOMMDATA = WM_USER + 1;
        public static readonly int PWM_REQUESTHANGUP = WM_USER + 2;
        public static readonly int PWM_THREADREADY = WM_USER + 3;
        public static readonly int PWM_COMMWRITE = WM_USER + 1;
