        public static string CommsLogFile = "";
        internal static string CommsLogName = "";

        // Delphi: procedure LogDebugInfo(outstr: PChar)
        public static void LogDebugInfo(string outstr)
        {
            if (CommsLogName != "")
            {
                Rtl.WriteLn(CommsLogFile, outstr);
            }
        }

        // Delphi: procedure LogDebugLastError(dwLastError: DWORD; szPrefix: PChar)
        public static void LogDebugLastError(uint dwLastError, string szPrefix)
        {
            string szLastError = "";
            char[] szOutputLastError = new char[4096];
            if (szPrefix == null)
            {
                szPrefix = "";
            }
            szLastError = Misc.szFormatLastError(dwLastError, null, 0);
            if (szLastError == null)
            {
                wsprintf(szOutputLastError, Rtl.PChar(szPrefix + "Out of memory"));
                LogDebugInfo(Rtl.StrPas(szOutputLastError));
                return;
            }
            wsprintf(szOutputLastError, Rtl.PChar(szPrefix + "GetLastError returned: \"" + szLastError + "\""));
            LocalFree((uint)szLastError);
            LogDebugInfo(Rtl.StrPas(szOutputLastError));
        }

        /// <summary>
        /// Code from the unit&apos;s initialization section (called at application start-up).
        /// </summary>
        public static void Initialization()
        {
        }
    }
